### 3. Using a Random Seed Generator
# You can use a random seed generator to create unique seeds for each test case.

import numpy as np


def generate_test_case(base_state_seed, base_noise_seed, num_cases):
    rng_base = np.random.default_rng(seed=0)  # Base RNG to generate seeds

    test_cases = []
    for i in range(num_cases):
        state_seed = (rng_base.integers(0, 2**32) + base_state_seed) % (2**32)
        noise_seed = (rng_base.integers(0, 2**32) + base_noise_seed) % (2**32)

        rng_state = np.random.default_rng(seed=state_seed)
        rng_noise = np.random.default_rng(seed=noise_seed)

        state = rng_state.normal(size=(10,))
        noise = rng_noise.normal(size=(10,))

        test_cases.append((state, noise))

    return test_cases


